/** Static local task validation before any restored artifact leaves the catalog. */
import { foldTasks } from '@deepseek-ai/dsh-task-checkpoint/fold'
import type { SessionEvent } from '@deepseek-ai/dsh-session'
import type { SessionFormatCatalog, SessionFormatRestoreOptions } from '@deepseek-ai/dsh-session-format'

/** Validate task replay for both current and transformed reads, before live restoration can append events.
 * @param catalog - unmodified historical migration and codec assembly.
 * @returns a local catalog preserving physical and historical refusal rules.
 */
export function withLocalTaskAdmission(catalog: SessionFormatCatalog): SessionFormatCatalog {
  return Object.freeze({
    ...catalog,
    createRestore(header: unknown, options: SessionFormatRestoreOptions) {
      const restore = catalog.createRestore(header, options)
      return {
        header: restore.header,
        decodeRow(row: unknown) { restore.decodeRow(row) },
        finish() {
          const artifact = restore.finish()
          foldTasks(artifact.events as unknown as readonly SessionEvent[], Number.MAX_SAFE_INTEGER)
          return artifact
        },
      }
    },
  })
}


